// Ģenerēts ar tools/bundle_shaders.py no mapes shaders/. Nelabot ar roku.
export const SHADERS = {
"common": "// piliens.lv v2: kopīgā GLSL bibliotēka (troksnis, šūnas, krāsas)\n// Visas funkcijas atkarīgas no uSeed, lai katra apmeklējuma aina būtu cita.\nprecision highp float;\nuniform vec2 uRes;\nuniform float uTime;\nuniform float uSeed;\nuniform vec2 uMouse;\nout vec4 outColor;\n\n#define PI 3.14159265\n#define SAT(x) clamp(x, 0.0, 1.0)\n\nvec2 seedOff() { return vec2(fract(uSeed * 0.1031) * 913.0, fract(uSeed * 0.0973) * 677.0); }\n\nfloat hash12(vec2 p) {\n  p += seedOff();\n  vec3 p3 = fract(vec3(p.xyx) * .1031);\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.x + p3.y) * p3.z);\n}\nvec2 hash22(vec2 p) {\n  p += seedOff();\n  vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));\n  p3 += dot(p3, p3.yzx + 33.33);\n  return fract((p3.xx + p3.yz) * p3.zy);\n}\nvec3 hash32(vec2 p) {\n  p += seedOff();\n  vec3 p3 = fract(vec3(p.xyx) * vec3(.1031, .1030, .0973));\n  p3 += dot(p3, p3.yxz + 33.33);\n  return fract((p3.xxy + p3.yzz) * p3.zyx);\n}\n\n// gradienta troksnis ar gludu atvasinājumu\nfloat gnoise(vec2 p) {\n  vec2 i = floor(p), f = fract(p);\n  vec2 u = f * f * f * (f * (f * 6. - 15.) + 10.);\n  vec2 ga = hash22(i) * 2. - 1., gb = hash22(i + vec2(1, 0)) * 2. - 1.;\n  vec2 gc = hash22(i + vec2(0, 1)) * 2. - 1., gd = hash22(i + vec2(1, 1)) * 2. - 1.;\n  float a = dot(ga, f), b = dot(gb, f - vec2(1, 0)), c = dot(gc, f - vec2(0, 1)), d = dot(gd, f - vec2(1, 1));\n  return mix(mix(a, b, u.x), mix(c, d, u.x), u.y) * 1.4142;\n}\nfloat fbm(vec2 p, int oct) {\n  float s = 0., a = .5;\n  mat2 r = mat2(.8, .6, -.6, .8);\n  for (int i = 0; i < 8; i++) { if (i >= oct) break; s += a * gnoise(p); p = r * p * 2.03 + 17.1; a *= .5; }\n  return s;\n}\nfloat ridged(vec2 p, int oct) {\n  float s = 0., a = .5;\n  mat2 r = mat2(.8, .6, -.6, .8);\n  for (int i = 0; i < 8; i++) { if (i >= oct) break; s += a * (1. - abs(gnoise(p))); p = r * p * 2.01 + 9.3; a *= .5; }\n  return s;\n}\nvec2 warp(vec2 p, float k) { return p + k * vec2(fbm(p + 3.1, 4), fbm(p + 7.7, 4)); }\n\n// Voronoja šūnas: x = attālums līdz tuvākajam, y = F2-F1 (mala), zw = šūnas centrs\nvec4 voronoi(vec2 x, float jitter) {\n  vec2 n = floor(x), f = fract(x);\n  float d1 = 8., d2 = 8.; vec2 c1 = vec2(0);\n  for (int j = -1; j <= 1; j++) for (int i = -1; i <= 1; i++) {\n    vec2 g = vec2(i, j);\n    vec2 o = hash22(n + g) * jitter + (1. - jitter) * .5;\n    vec2 r = g + o - f;\n    float d = dot(r, r);\n    if (d < d1) { d2 = d1; d1 = d; c1 = n + g + o; } else if (d < d2) d2 = d;\n  }\n  return vec4(sqrt(d1), sqrt(d2) - sqrt(d1), c1);\n}\n\n// krāsu korekcija: ACES tuvinājums, gamma, smalks grauds\nvec3 aces(vec3 x) { return SAT((x * (2.51 * x + .03)) / (x * (2.43 * x + .59) + .14)); }\nvec3 finish(vec3 c, vec2 fragCoord) {\n  c = aces(c);\n  c = pow(c, vec3(1. / 2.2));\n  c += (hash12(fragCoord + fract(uTime) * 91.) - .5) * (1.6 / 255.);\n  return c;\n}\nfloat luma(vec3 c) { return dot(c, vec3(.2126, .7152, .0722)); }\n\n// piliena forma (SDF): smaile augšā, apaļš dibens; p relatīvi pret dibena centru, r rādiuss, h smailes augstums virs centra\nfloat sdDrop(vec2 p, float r, float h) {\n  p.x = abs(p.x);\n  if (p.y < 0.) return length(p) - r;              // apakšējā puse: aplis\n  float t = SAT(p.y / h);\n  float w = r * sqrt(max(0., 1. - t)) * (1. - .15 * t); // sašaurinās uz augšu\n  return max(p.x - w, p.y - h) * .9;\n}\n\n// fotogrāfija ar \"cover\" izgriezumu ap fokusa punktu; atgriež lineāru krāsu\nvec3 photoCover(sampler2D t, vec2 uv, float imgAsp, vec2 focus, bool flipX) {\n  float scrAsp = uRes.x / uRes.y;\n  vec2 sc = imgAsp > scrAsp ? vec2(scrAsp / imgAsp, 1.) : vec2(1., imgAsp / scrAsp);\n  vec2 o = clamp(focus - sc * .5, vec2(0), vec2(1) - sc);\n  vec2 tc = o + uv * sc;\n  if (flipX) tc.x = 1. - tc.x;\n  return pow(texture(t, tc).rgb, vec3(2.2));\n}\n",
"kaje": "// kājene: Daiņa foto no Baltijas jūras krasta (aļģēm apauguši laukakmeņi);\n// virs tā: lēni viļņi un putas seklajā ūdenī, dzintara gabaliņi starp akmeņiem\nuniform float uRnd[32];\nuniform sampler2D uTex0;\nuniform float uBgAspect;\n\nvoid main() {\n  vec2 fc = gl_FragCoord.xy;\n  float asp = uRes.x / uRes.y;\n  vec2 uv = fc / uRes;\n  vec2 p = (fc - .5 * uRes) / uRes.y;\n  bool mobile = asp < .9;\n  vec2 focus = mobile ? vec2(.45, .5) : vec2(.5, .5);\n\n  // seklā ūdens kustība: gaisma ņirb un bilde viegli izkropļojas tikai ūdens vietās\n  vec3 base = photoCover(uTex0, uv, uBgAspect, focus, false);\n  float waterish = smoothstep(.06, .0, abs(base.g - base.b - .0)) * smoothstep(.55, .25, uv.y) * smoothstep(.12, .3, luma(base));\n  vec2 flow = .004 * vec2(gnoise(p * 9. + uTime * .3), gnoise(p * 9. + 4. + uTime * .3)) * waterish;\n  vec3 col = photoCover(uTex0, uv + flow, uBgAspect, focus, false);\n\n  // putu mežģīnes pēc viļņa: tikai ūdenī, sekojot krasta līnijai\n  float lace = 0.;\n  for (int i = 0; i < 3; i++) {\n    float fi = float(i);\n    float ly = .18 + .09 * fi + .03 * fbm(vec2(p.x * 2. + fi * 3., fi), 3);\n    float band = smoothstep(.025, .0, abs(uv.y - ly));\n    float holes = smoothstep(.40, .62, voronoi(p * 70. + fi * 5., .9).y * 3.);\n    lace = max(lace, band * holes * (1. - fi * .25));\n  }\n  col = mix(col, vec3(.86, .87, .85), lace * waterish * .55);\n\n  // dzintara gabaliņi seklajā ūdenī priekšplānā; lielākajā lāse ar skuju no sveķu sadaļas\n  for (int i = 0; i < 6; i++) {\n    float fi = float(i);\n    vec2 c = vec2((mobile ? .55 : .66) + .28 * hash12(vec2(fi, 3.)) - .5, .04 + .11 * hash12(vec2(fi, 5.)));\n    c = (c - .5) * vec2(asp, 1.) + vec2(0., 0.);\n    c = vec2(c.x, c.y);\n    c = (vec2(.62 + .3 * hash12(vec2(fi, 3.)), .05 + .10 * hash12(vec2(fi, 5.))) - .5) * vec2(asp, 1.);\n    float r = i == 0 ? .020 : .007 + .010 * pow(hash12(vec2(fi, 7.)), 2.);\n    vec2 q = (p - c) / r;\n    float d = length(q * vec2(1., 1.25)) - 1. - .22 * gnoise(q * 1.7 + fi * 3.);\n    if (d < .6) col *= 1. - .22 * smoothstep(.6, .0, d) * step(-.1, d);   // kontakta ēna\n    if (d < 0.) {\n      float h = SAT(-d * 1.4);\n      vec3 am = mix(vec3(.42, .14, .02), vec3(.96, .58, .16), h * .85 + .15);\n      am += vec3(1., .9, .75) * exp(-dot(q - vec2(-.3, .38), q - vec2(-.3, .38)) * 7.) * .7;\n      am = mix(am, am * .65 + vec3(.05, .07, .08), .45);\n      am += vec3(.9) * smoothstep(.06, .0, abs(gnoise(q * 3. + fi) )) * .08;                  // zem ūdens: vēsāks, blāvāks\n      if (i == 0) am = mix(am, vec3(.30, .14, .04), smoothstep(.10, .0, abs(q.y - q.x * .45)) * step(abs(q.x), .55) * .75);\n      col = mix(col, am, smoothstep(.0, -.12, d));\n    }\n  }\n  // mīksta tumšāka migla apakšā aiz paraksta un labajā malā aiz navigācijas\n  col = mix(col, col * .45, smoothstep(.55, .0, length((uv - vec2(0., 0.)) * vec2(asp * .9, 1.6))) * .8);\n  col = mix(col, col * .55, smoothstep(.3, .0, length((uv - vec2(1., .5)) * vec2(asp * 1.4, .75))) * .7);\n  col = pow(max(col, 0.), vec3(1. / 2.2));\n  col += (hash12(fc) - .5) * (1.5 / 255.);\n  outColor = vec4(col, 1.);\n}\n",
"laiks": "// laiks: no lāstekas zem mitras klints pārkares pil bļodakmenī; apkārt sūnas un papardes; apmācies rīts mežā\nuniform float uRnd[32];\n\nconst vec3 KEY = vec3(.86, .90, .92);\nconst vec3 AMB = vec3(.075, .10, .085);\nvec3 Ld = normalize(vec3(-.45, .80, .40));\n\nuniform sampler2D uTex0;\nuniform sampler2D uTex1;\nuniform sampler2D uTex2;   // ķērpji un sūnas (Daiņa tuvplāns)\n// īstā sūna no Daiņa bildes (bildes apakšējā trešdaļa ir sūnu grīda)\nvec3 realMoss(vec2 p) {\n  vec2 w = p * 1.6 + .25 * vec2(fbm(p * 3., 3), fbm(p * 3. + 5., 3));\n  vec2 tc = vec2(.08 + .84 * fract(w.x * .45), .03 + .22 * fract(w.y * .7));\n  return pow(texture(uTex1, tc).rgb, vec3(2.2));\n}\nuniform float uBgAspect;\nuniform float uLevel;    // ūdens līmenis iedobē 0..1\nuniform float uPhase;    // pašreizējās sekundes fāze: lāse briest un krīt\nuniform float uRipple;   // sekundes kopš pēdējā piliena\nuniform float uGreen;    // sūnas zaļums 0..1 (aug ar pilieniem)\nuniform float uIcicle;   // lāsteka īsinās 0..1\nuniform float uOverflow; // pārplūšana 0..1\n// fons: Daiņa fotogrāfija no sūnaina egļu meža, izplūdusi kā aiz objektīva\nvec3 bgForest(vec2 uv, float blur) {\n  vec3 c = photoCover(uTex0, clamp(uv, 0., 1.), uBgAspect, vec2(.5, .42), false);\n  c *= vec3(.62, .66, .62);                       // nedaudz tumšāks, lai priekšplāns izceļas\n  c = mix(c, vec3(luma(c)) * vec3(.9, 1., .95), .15);\n  return c;\n}\n\nfloat boulderSDF(vec2 p, vec2 c, vec2 rad) {\n  vec2 q = (p - c) / rad;\n  float ang = atan(q.y, q.x);\n  float n = .05 * fbm(vec2(ang * 2., 1.), 4) + .02 * gnoise(vec2(ang * 9., 2.));\n  return (length(q) - 1. - n) * min(rad.x, rad.y);\n}\n\n// paparde: mugurkauls ar lancetiskām lapiņām; atgriež (attālums, lapiņas iekšējā koordināte)\nvec2 fern(vec2 p, vec2 base, float ang, float len, float curl) {\n  float d = 1., inner = 0.;\n  vec2 dir = vec2(cos(ang), sin(ang)), nrm = vec2(-dir.y, dir.x);\n  for (int i = 0; i < 26; i++) {\n    float t = float(i) / 25.;\n    vec2 sp = base + dir * len * t + nrm * curl * t * t * len;\n    vec2 tang = normalize(dir + nrm * 2. * curl * t);\n    vec2 tn = vec2(-tang.y, tang.x);\n    float lw = len * .13 * pow(sin(PI * min(1., t * 1.08 + .04)), .8);\n    for (int k = -1; k <= 1; k += 2) {\n      vec2 ax = normalize(tn * float(k) + tang * .55);\n      vec2 lc = sp + ax * lw * .5;\n      vec2 q = p - lc;\n      float u = dot(q, ax) / max(lw * .55, 1e-4), v = dot(q, vec2(-ax.y, ax.x)) / max(lw * .15, 1e-4);\n      float dd = length(vec2(u, v * (1. + .6 * abs(u)))) - 1.;\n      if (dd < d) { d = dd; inner = v; }\n    }\n    float sd = (length(p - sp) - len * .005) / (len * .02);\n    if (sd < d) { d = sd; inner = 0.; }\n  }\n  return vec2(d, inner);\n}\n\nvoid main() {\n  vec2 fc = gl_FragCoord.xy;\n  float asp = uRes.x / uRes.y;\n  vec2 uv = fc / uRes;\n  vec2 p = (fc - .5 * uRes) / uRes.y;\n  bool mobile = asp < .9;\n  float cx = mobile ? .04 * asp : .16 * asp;\n\n  vec3 col = bgForest(uv, 1.);\n\n  vec2 bc = vec2(cx, mobile ? -.32 : -.34), br = mobile ? vec2(.40 * asp, .16) : vec2(.32, .18);\n  // priekšplāns: izplūdusi sūna apakšmalā\n  float fg = smoothstep(-.42, -.5, p.y + .03 * fbm(vec2(p.x * 3., 2.), 3));\n  col = mix(col, vec3(.05, .09, .02) + vec3(.06, .09, .02) * fbm(p * 8., 3), fg * .9);\n  // ēna zem akmens\n  col *= 1. - .6 * smoothstep(.15, -.05, length((p - bc - vec2(.03, -.12)) / (br * vec2(1.2, .5))) - 1.);\n\n  float bd = boulderSDF(p, bc, br);\n  vec2 cc = bc + vec2(-.01, br.y * .45);\n  vec2 cr = vec2(br.x * .40, br.y * .16);\n  if (bd < 0.) {\n    vec2 q = (p - bc) / br;\n    vec3 n = normalize(vec3(q.x * .95, q.y * .8 + .4, sqrt(max(.05, 1. - dot(q, q) * .85))));\n    n = normalize(n + .18 * vec3(fbm(p * 70., 3), fbm(p * 70. + 5., 3), 0));\n    // granīts: smalks graudainums, pelēks ar sārtiem un tumšiem graudiem\n    vec4 v = voronoi(p * 520., .9);\n    float grain = hash12(v.zw);\n    vec3 gr = mix(vec3(.20, .195, .19), vec3(.27, .21, .19), step(.65, grain));\n    gr = mix(gr, vec3(.08, .08, .085), step(.88, grain) * .7);\n    gr *= .78 + .35 * fbm(p * 24., 4);\n    // ķērpji un sūnas\n    float moss = smoothstep(.0, .35, n.y + .6 * fbm(p * 9. + 3., 5) + .05 - .2 * smoothstep(.1, -.9, q.y));\n    float fuzz = fbm(p * 420., 3);\n    vec3 mc = realMoss(p) * .6 * (.55 + .6 * max(dot(n, Ld), 0.));\n    mc = mix(vec3(luma(mc)) * vec3(1.05, 1., .82), mc * vec3(.95, 1.12, .85), .45 + .55 * uGreen);\n    float lichen = smoothstep(.55, .7, fbm(p * 26. + 9., 4)) * (1. - moss);\n    vec3 alb = mix(gr, vec3(.42, .45, .36), lichen * .6);\n    alb = mix(alb, mc, moss);\n    // slapja svītra, pa kuru ūdens pārplūst uz strautiņu\n    float wx = bc.x + br.x * .38 + .012 * gnoise(vec2(p.y * 18., 3.));\n    float wet = smoothstep(.022, .0, abs(p.x - wx)) * step(p.y, cc.y) * (.25 + .75 * uOverflow);\n    float flowHL = uOverflow * smoothstep(.012, .0, abs(p.x - wx)) * step(p.y, cc.y) * pow(SAT(gnoise(vec2(p.x * 60., p.y * 25. + uTime * 4.)) + .2), 3.);\n    alb *= 1. - .45 * wet;\n    float dif = max(dot(n, Ld), 0.);\n    float ao = .45 + .55 * smoothstep(-1., .5, q.y);\n    vec3 lit = alb * (KEY * dif + AMB * 2.2 * ao);\n    lit += vec3(.8, .85, .85) * flowHL * .6;\n    lit += vec3(.6, .65, .65) * wet * pow(max(dot(reflect(-Ld, n), vec3(0, 0, 1)), 0.), 24.) * .5;\n    lit += vec3(.4, .45, .45) * (1. - moss) * pow(max(dot(reflect(-Ld, n), vec3(0, 0, 1)), 0.), 40.) * .08;\n    // iedobe ar ūdeni\n    vec2 cq = (p - cc) / cr;\n    float cav = length(cq) - 1. - .06 * fbm(vec2(atan(cq.y, cq.x) * 3., 4.), 3);\n    float lip = smoothstep(.25, .0, cav) * step(0., cav);\n    lit *= 1. - .35 * lip * smoothstep(0., -1., cq.y);\n    if (cav < 0.) {\n      float rr = length(cq);\n      float front = uRipple * 1.3;\n      float ripple = sin((rr - front) * 34.) * exp(-pow((rr - front) * 3.2, 2.)) * exp(-uRipple * 1.6)\n                   + .25 * sin((rr - front * .6) * 22.) * exp(-pow((rr - front * .6) * 2.5, 2.)) * exp(-uRipple * 2.2);\n      vec2 rn = cq / max(rr, 1e-3) * ripple * .06;\n      // atspulgs: gaišas debess sprauga un tumša pārkare\n      vec2 ruv = vec2(uv.x + rn.x, 1. - (uv.y - .1) * .6 + rn.y);\n      vec3 refl = bgForest(clamp(ruv, 0., 1.), 1.) * 1.4 + vec3(.10, .12, .12) * smoothstep(.6, -.4, cq.y + rn.y * 6.);\n      float fres = .35 + .5 * pow(SAT(1. - (cq.y * .5 + .5)), 2.);\n      vec3 inside = vec3(.03, .035, .025);\n      vec3 water = mix(inside, refl, fres);\n      water += vec3(.85, .9, .9) * smoothstep(.04, .0, abs(rr - .55 - .02 * ripple)) * .06;\n      water += vec3(1.) * exp(-dot(cq - vec2(-.35, .3), cq - vec2(-.35, .3)) * 30.) * .35;\n      // ūdens tikai līdz līmenim: virsmas elipse aug, iedobei pildoties\n      float wl = mix(.30, 1.02, uLevel);\n      float wMask = 1. - smoothstep(wl - .06, wl, rr + .03 * fbm(cq * 4., 2));\n      vec3 dryBowl = mix(vec3(.05, .05, .045), vec3(.13, .12, .11), smoothstep(-1., .6, cq.y)) * (.8 + .3 * fbm(p * 90., 3));\n      water = mix(dryBowl, water, wMask);\n      water += vec3(.7, .75, .75) * smoothstep(.02, .0, abs(rr - wl + .01)) * wMask * .12;   // menisks\n      lit = mix(water, lit, smoothstep(-.12, .0, cav) * .5);\n    }\n    col = mix(col, lit, 1. - smoothstep(-.003, .0, bd));\n  }\n\n  // papardes: aizmugurē tumšākas, priekšā gaišākas\n  for (int f = 0; f < 3; f++) {\n    float ff = float(f);\n    float side = (f == 1) ? 1. : -1.;\n    vec2 base = bc + vec2(side * br.x * (.72 + .3 * hash12(vec2(ff, 1.))), -br.y * (.1 + .3 * hash12(vec2(ff, 7.))));\n    float ang = PI * .5 + side * (.30 + .55 * hash12(vec2(ff, 2.)));\n    float len = (.36 + .14 * hash12(vec2(ff, 3.))) * (mobile ? .75 : 1.);\n    float curl = -side * (.38 + .18 * hash12(vec2(ff, 4.)));\n    vec2 fd = fern(p, base, ang, len, curl);\n    float cov = (1. - smoothstep(-.35, .25, fd.x)) * .85;\n    if (cov > 0.) {\n      float tone = .55 + .45 * hash12(vec2(ff, 9.));\n      vec3 fcol = mix(vec3(.02, .06, .01), vec3(.08, .18, .03), tone);\n      fcol *= .65 + .55 * (1. - abs(fd.y)) * smoothstep(.0, -.35, fd.x);                        // vidusdzīsla gaišāka\n      fcol *= KEY * .9 + AMB * 2.;\n      fcol += vec3(.10, .16, .06) * pow(SAT(1. - abs(fd.y - .5)), 8.) * .3;\n      col = mix(col, fcol, cov * .97);\n    }\n  }\n  // jauna, vēl satīta paparde (gliemežvāks), kas atritināsies\n  vec2 kc = bc + vec2(-br.x * .55, br.y * .55);\n  vec2 kq = p - kc;\n  float kr = length(kq), ka = atan(kq.y, kq.x);\n  float spiral = abs(fract((log(max(kr, 1e-4)) * 3.2 - ka / (2. * PI)) ) - .5) * kr * 6.;\n  float kS = 1. - .7 * uGreen;\n  float koru = (kr < .028 * kS && kr > .004 * kS) ? spiral - .02 * kS : 1.;\n  float stem = abs(p.x - kc.x - .006 - .01 * (kc.y - p.y) * 8.) - .0025;\n  stem = (p.y < kc.y - .02 && p.y > bc.y + br.y * .3) ? stem : 1.;\n  if (min(koru, stem) < 0.) col = mix(col, vec3(.18, .30, .07) * (KEY + AMB), .95);\n\n  // klints pārkare: tumšs, slapjš akmens, sūnas tikai virspusē\n  float topY = (mobile ? .26 : .30) + .05 * fbm(vec2(p.x * 2.6 + 2., 1.), 4) + .012 * gnoise(vec2(p.x * 30., 3.)) + .55 * max(0., (mobile ? -.05 : .2) * asp - p.x);\n  float edgeL = -10.;\n  float od = max(topY - p.y, edgeL - p.x);\n  if (od < 0.) {\n    float depthIn = SAT((p.y - topY) * 5.);\n    vec3 rc = mix(vec3(.025, .025, .024), vec3(.10, .095, .085), .5 + .5 * fbm(p * 34., 5));\n    float drip = pow(SAT(fbm(vec2(p.x * 40., p.y * 3.), 3) + .35), 5.);\n    vec3 lit = rc * (.25 + .9 * depthIn) + vec3(.5, .55, .55) * drip * .12 * (1. - depthIn);\n    vec2 kq = p * vec2(.55, 1.2) + vec2(.12, .1) + .08 * vec2(fbm(p * 4., 3), fbm(p * 4. + 7., 3));\n    vec3 rm = pow(texture(uTex2, kq).rgb, vec3(2.2)) * .55 * (.35 + .65 * depthIn);\n    float topMoss = smoothstep(.0, .35, fbm(p * 5. + 4., 4) + .35 + (p.y - topY) * 3.);\n    vec3 mc = mix(vec3(.02, .045, .01), vec3(.08, .14, .025), .5 + .5 * fbm(p * 300., 3));\n    lit = mix(lit, rm, SAT(topMoss));\n    col = mix(col, lit, 1. - smoothstep(-.003, .0, od));\n  }\n  // nokarenas sūnu šķiedras gar apakšmalu\n  for (int i = 0; i < 18; i++) {\n    float fi = float(i);\n    float x = (mobile ? -.05 : .2) * asp + hash12(vec2(fi, 21.)) * (.3 * asp);\n    float ty = (mobile ? .26 : .30) + .05 * fbm(vec2(x * 2.6 + 2., 1.), 4) + .55 * max(0., (mobile ? -.05 : .2) * asp - x);\n    float l = .01 + .045 * pow(hash12(vec2(fi, 22.)), 2.);\n    float dx = abs(p.x - x - .003 * sin(p.y * 90. + fi));\n    float m = (1. - smoothstep(.001, .003, dx)) * step(ty - l, p.y) * step(p.y, ty + .005);\n    col = mix(col, vec3(.07, .12, .03), m * .85);\n  }\n\n  // lāsteka\n  float ix = cc.x + .003;\n  float iTop = (mobile ? .26 : .30) + .05 * fbm(vec2(ix * 2.6 + 2., 1.), 4) + .55 * max(0., (mobile ? -.05 : .2) * asp - ix);\n  float iLen = (mobile ? .17 : .21) * (.8 + .3 * uRnd[0]) * (1. - .25 * uIcicle);\n  float t = SAT((iTop - p.y) / iLen);\n  float iw = .020 * pow(1. - t, 1.5) + .0012 + .002 * gnoise(vec2(p.y * 40., 2.)) * (1. - t);\n  float icx = ix + .003 * gnoise(vec2(p.y * 25., 1.));\n  float id = abs(p.x - icx) - iw;\n  if (id < 0. && p.y < iTop + .01 && p.y > iTop - iLen) {\n    float xn = (p.x - icx) / iw;\n    vec3 refr = bgForest(uv + vec2(-xn * .03, .02), 1.);\n    vec3 ice = refr * 1.6 + vec3(.10, .13, .14);\n    ice = mix(ice, vec3(.70, .78, .80), .18 + .2 * fbm(vec2(p.x * 300., p.y * 40.), 3));  // duļķaini slāņi\n    ice += vec3(.95) * pow(SAT(1. - abs(xn + .5) * 4.), 3.) * .65;\n    ice += vec3(.5) * pow(SAT(1. - abs(xn - .7) * 6.), 3.) * .2;\n    col = mix(col, ice, .95 * (1. - smoothstep(-.0015, .0, id)));\n  }\n  vec2 tip = vec2(ix, iTop - iLen);\n  // lāse briest pie lāstekas gala (fāze 0..0.6), tad krīt līdz ūdenim (0.6..1)\n  float grow = SAT(uPhase / .6);\n  float r0 = .0068 * (grow * grow * (3. - 2. * grow));\n  r0 = uPhase < .6 ? r0 : 0.;\n  float d0 = r0 > .0004 ? sdDrop(p - (tip - vec2(0, r0 * 1.05)), r0, r0 * 1.9) : 1.;\n  float ft = SAT((uPhase - .6) / .4);\n  float surfY = cc.y + .004;\n  vec2 fallC = vec2(ix, mix(tip.y - .006, surfY, ft * ft));\n  float d1 = uPhase >= .6 ? sdDrop(p - fallC, .006, .016 + ft * .012) : 1.;\n  float dd = min(d0, d1);\n  if (dd < 0.) {\n    vec3 refr = bgForest(vec2(uv.x, 1. - uv.y), 1.) * 1.5;\n    col = mix(col, refr + vec3(.08, .1, .1), .9);\n  }\n  float hl = min(uPhase >= .6 ? length(p - fallC - vec2(-.0018, .0015)) : 1., r0 > .002 ? length(p - tip + vec2(.0018, r0 * .8)) : 1.);\n  col += vec3(.9) * smoothstep(.0022, .0, hl);\n\n  col *= .72 + .28 * smoothstep(1.2, .3, length((uv - vec2(.58, .48)) * vec2(asp * .7, 1.)));\n  outColor = vec4(finish(col * 1.25, fc), 1.);\n}\n",
"lase": "// lāse: sekla Latvijas upe no augšas; granīta un dolomīta oļi, smilšu viļņojums, skujas, kaustiku tīkls, ūdensmērītājs\nuniform float uRnd[32];\nuniform sampler2D uTex0;   // vārdi smiltīs (maska)\n\nuniform sampler2D uTex1;   // viļņu simulācija\nuniform vec2 uStrider;     // ūdensmērītāja vieta (p koordinātās)\nuniform float uStriderA;   // pagrieziena leņķis\nuniform vec4 uFish;        // zivtiņas ēna: x, y, virziens, redzamība\n\n// ūdens virsmas augstums: simulētie viļņi + straumes ņirbas + ūdensmērītāja kāju iedobītes\nfloat surfaceH(vec2 p) {\n  float asp = uRes.x / uRes.y;\n  vec2 q = p * vec2(1. / asp, 1.) + .5;\n  float h = texture(uTex1, q).r * .010;\n  h += .006 * fbm(p * 5. + vec2(uTime * .25, 0.), 4);\n  for (int k = 0; k < 6; k++) {\n    float a = float(k) * 1.047 + .5 + uStriderA;\n    vec2 lp = uStrider + vec2(cos(a) * .07, sin(a) * .045);\n    h -= .006 * exp(-dot(p - lp, p - lp) / .00012);\n  }\n  return h;\n}\n\nvec3 riverbed(vec2 p, vec2 uv) {\n  // smiltis ar viļņojumu (ripple marks), kas iet šķērsām straumei\n  float ripple = sin((p.y + .06 * fbm(p * 3., 3)) * 90. + 3. * fbm(p * 6., 3));\n  vec3 sand = mix(vec3(.42, .27, .16), vec3(.62, .44, .28), .5 + .5 * fbm(p * 30., 4));\n  sand *= .88 + .12 * ripple;\n  vec3 c = sand;\n  float hgt = .3 * ripple;\n  // oļi: dažāda izmēra (log-normāli), dažāds iezis\n  for (int layer = 0; layer < 3; layer++) {\n    float sc = layer == 0 ? 3.2 : (layer == 1 ? 8. : 24.);\n    vec4 v = voronoi(p * sc + float(layer) * 7.1, .85);\n    float rnd = hash12(v.zw + float(layer) * 3.);\n    float keep = layer == 0 ? .45 : (layer == 1 ? .2 : .05);\n    if (rnd < keep) continue;\n    float rad = (.18 + .22 * hash12(v.zw + 9.)) * (layer == 0 ? 1.2 : 1.);\n    vec2 cc = v.zw / sc;\n    vec2 d = p - cc + .03 / sc * vec2(fbm(p * 20., 2), fbm(p * 20. + 4., 2));\n    float ang = hash12(v.zw + 5.) * PI;\n    d = mat2(cos(ang), -sin(ang), sin(ang), cos(ang)) * d;\n    float e = length(d * vec2(1., 1.25 + .5 * hash12(v.zw + 2.)) * sc) / rad;\n    if (e < 1.) {\n      float kind = hash12(v.zw + 11.);\n      vec3 rock = kind < .4 ? vec3(.36, .34, .33) : (kind < .62 ? vec3(.50, .30, .24) : (kind < .85 ? vec3(.66, .60, .48) : vec3(.18, .19, .18)));\n      vec4 g = voronoi(p * 300., .9);\n      rock *= .8 + .35 * hash12(g.zw) * (kind < .62 ? 1. : .4) + .15 * fbm(p * 60., 3);\n      float dome = sqrt(1. - e * e);\n      rock *= .55 + .45 * dome;\n      // aļģu apsūbējums oļu augšpusē\n      rock = mix(rock, vec3(.20, .26, .10), .35 * smoothstep(.2, .8, fbm(p * 40. + 3., 3)) * dome);\n      c = mix(c, rock, smoothstep(1., .9, e));\n      hgt = max(hgt, dome);\n    } else {\n      c *= 1. - .3 * smoothstep(1.35, 1., e);    // kontakta ēna smiltīs\n    }\n  }\n  // vārdi, iespiesti smiltīs\n  float word = texture(uTex0, uv).r;\n  c = mix(c, c * .62, word * (1. - step(.5, hgt)) * .9);\n  c += vec3(.08) * smoothstep(.0, .4, texture(uTex0, uv + vec2(-.0015, .002)).r - word) * (1. - step(.5, hgt));\n  // nogrimušas skujas un bērza lapa\n  for (int i = 0; i < 9; i++) {\n    float fi = float(i);\n    vec2 a = vec2(-.7 + 1.4 * hash12(vec2(fi, 1.)), -.45 + .9 * hash12(vec2(fi, 2.)));\n    float an = hash12(vec2(fi, 3.)) * PI;\n    vec2 dir = vec2(cos(an), sin(an));\n    float t = clamp(dot(p - a, dir), 0., .045);\n    float d = length(p - a - dir * t);\n    c = mix(c, vec3(.32, .18, .07), smoothstep(.0028, .0012, d) * .9);\n  }\n  vec2 lq = p - vec2(-.25 + .2 * uRnd[16], -.2 + .15 * uRnd[17]);\n  float la = uRnd[18] * PI; lq = mat2(cos(la), -sin(la), sin(la), cos(la)) * lq;\n  float leaf = length(lq * vec2(1., 1.5)) - .035 - .006 * sin(atan(lq.y, lq.x) * 14.);\n  c = mix(c, vec3(.55, .40, .12) * (.8 + .2 * fbm(p * 80., 2)), smoothstep(.002, -.002, leaf) * .9);\n  return c;\n}\n\nvoid main() {\n  vec2 fc = gl_FragCoord.xy;\n  float asp = uRes.x / uRes.y;\n  vec2 uv = fc / uRes;\n  vec2 p = (fc - .5 * uRes) / uRes.y;\n\n  // virsmas normāle\n  float e = .0025;\n  float h0 = surfaceH(p);\n  vec2 gr = vec2(surfaceH(p + vec2(e, 0)) - h0, surfaceH(p + vec2(0, e)) - h0) / e;\n  vec3 n = normalize(vec3(-gr, 1.));\n\n  // laušana: gultnes punkts nobīdās pēc slīpuma (ūdens dziļums ~ .12)\n  float depth = .05 + .16 * smoothstep(-.35, .55, fbm(p * 1.1 + 2., 4));\n  vec2 bp = p - gr * depth * .75;\n  vec2 buv = bp * vec2(1. / asp, 1.) + .5;\n  vec3 bed = riverbed(bp, buv);\n\n  // kaustikas: gaisma koncentrējas tur, kur virsma ieliekta (Laplasa operators)\n  float lap = (surfaceH(p + vec2(e, 0)) + surfaceH(p - vec2(e, 0)) + surfaceH(p + vec2(0, e)) + surfaceH(p - vec2(0, e)) - 4. * h0) / (e * e);\n  float caustic = SAT(-lap * .045);\n  // smalks kaustiku tīkls no straumes ņirbām (šūnu malas)\n  vec4 cv = voronoi(bp * 14. + uTime * .2 + .4 * vec2(fbm(bp * 4., 2), fbm(bp * 4. + 3., 2)), .9);\n  float net = pow(SAT(1. - cv.y * 2.6), 4.) * (.5 + .5 * fbm(bp * 3., 3));\n  vec3 sun = vec3(1.0, .93, .78);\n  vec3 col = bed * (.50 + .45 * net + caustic * .5) * sun;\n  // ūdensmērītāja ēnas uz gultnes: tumši diski ar gaišām malām (kājiņu iedobju lēcas)\n  vec2 st = uStrider + vec2(.05, -.06);\n  for (int k = 0; k < 6; k++) {\n    float a = float(k) * 1.047 + .5 + uStriderA;\n    vec2 lp = st + vec2(cos(a) * .07, sin(a) * .045);\n    float d = length(p - lp);\n    col *= 1. - .35 * smoothstep(.014, .006, d);\n    col += sun * .07 * smoothstep(.004, .0, abs(d - .014));\n  }\n  // zivtiņas ēna uz grunts\n  if (uFish.w > 0.) {\n    vec2 fq = bp - uFish.xy;\n    float fa = uFish.z;\n    fq = mat2(cos(fa), sin(fa), -sin(fa), cos(fa)) * fq;\n    float bodyF = length(fq * vec2(1., 3.2)) - .035;\n    float tail = length((fq + vec2(.045 + .006 * sin(uTime * 14.), 0.)) * vec2(1.6, 1.4)) - .014;\n    float fish = 1. - smoothstep(-.004, .012, min(bodyF, tail));\n    col *= 1. - .45 * fish * uFish.w;\n  }\n  // dziļums: ūdens krāsa un absorbcija\n  col *= mix(vec3(1.), vec3(.58, .34, .13), SAT(depth * 7.));\n  col = mix(col, vec3(.05, .025, .008), SAT((depth - .07) * 3.5));\n  // virsmas atspīdums: debess un koku lapotņu atspulgs + Freneļa\n  float fres = .02 + .98 * pow(1. - n.z, 5.);\n  vec3 sky = mix(vec3(.42, .50, .46), vec3(.04, .07, .03), smoothstep(.1, .5, fbm(uv * 2.5 + n.xy * 2., 4)));\n  col = mix(col, sky, SAT(fres * 1.6 + .03));\n  float spec = pow(max(dot(reflect(-normalize(vec3(.3, .5, .8)), n), vec3(0, 0, 1)), 0.), 200.);\n  col += sun * spec * 1.6;\n  // ūdensmērītājs: tievs ķermenis un kājiņas uz virsmas\n  vec2 sb = uStrider;\n  vec2 bq = p - sb; bq = mat2(cos(uStriderA), sin(uStriderA), -sin(uStriderA), cos(uStriderA)) * bq;\n  float body = length(bq * vec2(1., 3.5)) - .012;\n  float legs = 1.;\n  for (int k = 0; k < 6; k++) {\n    float a = float(k) * 1.047 + .5 + uStriderA;\n    vec2 lp = sb + vec2(cos(a) * .07, sin(a) * .045);\n    vec2 dir = lp - sb;\n    float t = SAT(dot(p - sb, dir) / dot(dir, dir));\n    legs = min(legs, length(p - sb - dir * t) - .0009);\n  }\n  col = mix(col, vec3(.05, .04, .03), smoothstep(.001, -.001, min(body, legs)) * .9);\n  // virspusē peldošas skujas un lapa\n  for (int i = 0; i < 4; i++) {\n    float fi = float(i);\n    vec2 a = vec2(-.6 + 1.2 * hash12(vec2(fi, 21.)), -.4 + .8 * hash12(vec2(fi, 22.)));\n    float an = hash12(vec2(fi, 23.)) * PI;\n    vec2 dir = vec2(cos(an), sin(an));\n    float t = clamp(dot(p - a, dir), 0., .05);\n    float d = length(p - a - dir * t);\n    col = mix(col, vec3(.40, .26, .10), smoothstep(.003, .0015, d));\n  }\n  // izplūdis priekšplāns: krasta zāles stiebri apakšējā kreisajā stūrī\n  float blades = 0.;\n  for (int i = 0; i < 9; i++) {\n    float fi = float(i);\n    float x0 = -.5 * asp + .03 + .25 * hash12(vec2(fi, 31.));\n    float bend = .3 + .4 * hash12(vec2(fi, 32.));\n    float y = p.y + .5;\n    float x = x0 + bend * y * y;\n    float w = .010 * (1. - y * 1.6);\n    blades = max(blades, smoothstep(w + .02, w * .2, abs(p.x - x)) * smoothstep(.5, .3, y) * step(.0, w));\n  }\n  col = mix(col, vec3(.04, .07, .02), blades * .85);\n  col *= .82 + .18 * smoothstep(1.2, .3, length((uv - .5) * vec2(asp * .7, 1.)));\n  col = mix(col, col * vec3(.7, .8, .65), .25);\n  outColor = vec4(finish(col * 1.05, fc), 1.);\n}\n",
"lase_sim": "// ūdens virsmas viļņu vienādojums: r = augstums tagad, g = augstums iepriekšējā solī\nuniform sampler2D uTex0;\nuniform vec4 uImp[8];   // x, y (0..1), rādiuss (pikseļos), stiprums\nuniform int uNI;\nuniform float uDamp;\nvoid main() {\n  vec2 px = 1. / uRes;\n  vec2 q = gl_FragCoord.xy * px;\n  vec2 c = texture(uTex0, q).rg;\n  float sum = texture(uTex0, q + vec2(px.x, 0)).r + texture(uTex0, q - vec2(px.x, 0)).r\n            + texture(uTex0, q + vec2(0, px.y)).r + texture(uTex0, q - vec2(0, px.y)).r;\n  float h = (sum * .5 - c.g) * uDamp;\n  for (int i = 0; i < 8; i++) {\n    if (i >= uNI) break;\n    vec2 d = (gl_FragCoord.xy - uImp[i].xy * uRes);\n    h += uImp[i].w * exp(-dot(d, d) / (uImp[i].z * uImp[i].z));\n  }\n  // krasti: viļņi pie malām izdziest\n  float edge = smoothstep(0., .02, q.x) * smoothstep(1., .98, q.x) * smoothstep(0., .02, q.y) * smoothstep(1., .98, q.y);\n  outColor = vec4(h * edge, c.r, 0, 1);\n}\n",
"lietus": "// lietus: vecs koka logs vakarā; aiz stikla lauki, priedes, bērzi un tāls lauku mājas logs;\n// stikls aprasojis, ar kursoru noslaucīta sliede, lāses kā lēcas\nuniform float uRnd[32];\n\nuniform sampler2D uTex0;   // sarmas rīts, ass\nuniform sampler2D uTex1;   // sarmas rīts, izplūdis\nuniform float uBgAspect;\nuniform sampler2D uTex2;   // lāšu normāļu karte\nuniform sampler2D uTex3;   // aprasojuma maska\n// aiz loga: Daiņa fotogrāfija (sarmota pļava, egles, saule lec labajā pusē)\nvec3 dusk(vec2 uv, float blur) {\n  vec2 f = vec2(.5, .80);\n  vec3 a = photoCover(uTex0, clamp(uv, 0., 1.), uBgAspect, f, false);\n  vec3 b = photoCover(uTex1, clamp(uv, 0., 1.), uBgAspect, f, false);\n  return mix(a, b, SAT(blur)) * .85;\n}\n\nvoid main() {\n  vec2 fc = gl_FragCoord.xy;\n  float asp = uRes.x / uRes.y;\n  vec2 uv = fc / uRes;\n  vec2 p = (fc - .5 * uRes) / uRes.y;\n  bool mobile = asp < .9;\n\n  // vecs stikls: viegls viļņainums\n  vec2 wob = .004 * vec2(fbm(vec2(uv.y * 3., 1.), 3), fbm(vec2(uv.x * 2., 4.), 3));\n  vec3 sharp = dusk(uv + wob, 0.);\n  vec3 blurred = dusk(uv + wob, 1.);\n\n  // aprasojums: uTex3 (r = 1 aprasojis, 0 noslaucīts), ko zīmē JS no kursora un slīdošajām lāsēm\n  float fogA = texture(uTex3, uv).a;\n  float fogN = .75 + .25 * fbm(p * 8., 4);\n  vec3 fog = mix(blurred * 1.2, vec3(.62, .62, .64), .45) * fogN + vec3(.02);\n  vec3 col = mix(sharp, fog, fogA);\n  col += vec3(.04) * fogA * fbm(p * 220., 2);\n  // noslaucītās vietas mala: kondensāta valnītis\n  float fe = texture(uTex3, uv + vec2(1.5 / uRes.x, 0)).a - texture(uTex3, uv - vec2(1.5 / uRes.x, 0)).a;\n  col += vec3(.10) * abs(fe) * 2.;\n\n  // lāses uz stikla: uTex2 (rg = normāle, b = pārklājums), ko zīmē JS no lāšu fizikas\n  vec4 dm = texture(uTex2, uv);\n  if (dm.b > .02) {\n    vec2 n = (dm.rg - .5) * 2.;\n    float h = sqrt(max(0., 1. - dot(n, n)));\n    vec2 suv = uv - n * vec2(.06 / asp, .06) * (1.2 + 2. * h);    // laušana: skats caur lāsi apgriezts un saspiests\n    vec3 dc = dusk(suv, .2) * 1.15;\n    dc *= 1. - .55 * smoothstep(.5, 1., length(n));\n    float spec = exp(-dot(n - vec2(-.38, .45), n - vec2(-.38, .45)) * 22.);\n    dc += vec3(1.) * spec * .85;\n    dc = mix(dc, fog, fogA * .65);       // lāses ir ārpusē; caur aprasojumu tās redzamas izplūdušas\n    col = mix(col, dc, smoothstep(.02, .35, dm.b));\n  }\n\n  // vecais koka rāmis: nobružāta balta krāsa, zem tās pelēks koks\n  float fx = mobile ? .035 * asp : .025 * asp;\n  float frameL = -.5 * asp + fx, frameR = .5 * asp - fx * 1.6;\n  float sash = .5 * asp - (mobile ? .0 : .38 * asp);   // vertikālā šķērslīste\n  float bars = min(min(p.x - frameL, frameR - p.x), mobile ? 1. : abs(p.x - (.18 * asp)) - .014);\n  float bottom = p.y + .5 - (mobile ? .05 : .065);\n  float fd = min(bars, bottom);\n  if (fd < 0.) {\n    vec2 wq = p * vec2(6., 60.);\n    if (bottom < 0. && bars > 0.) wq = p * vec2(60., 6.);\n    float grain = fbm(wq, 4);\n    vec3 wood = mix(vec3(.24, .21, .17), vec3(.36, .32, .26), .5 + .5 * grain);\n    float paint = smoothstep(-.2, .05, fbm(p * 22. + 3., 5) + .3);\n    vec3 pc = vec3(.82, .80, .74) * (.85 + .15 * grain);\n    vec3 fc2 = mix(wood, pc, paint);\n    // iekštelpas gaisma: silta no istabas, rāmis ēnā\n    fc2 *= vec3(.55, .48, .40) * (.6 + .4 * smoothstep(.0, -.02, fd));\n    col = mix(col, fc2, smoothstep(.0, -.004, fd));\n  }\n  // ēna un aprasojuma kondensāts pie rāmja malas\n  col *= 1. - .35 * smoothstep(.03, .0, abs(fd)) * step(0., fd);\n  col *= .85 + .15 * smoothstep(1.2, .3, length((uv - .5) * vec2(asp * .7, 1.)));\n  outColor = vec4(finish(col * 1.1, fc), 1.);\n}\n",
"piliens": "// piliens: rasas punkts. Fons: Daiņa sarmas rīts (saule labajā augšā, sarma kreisajā apakšā), izplūdis.\n// Burti: auksts, slapjš šīferis ar reljefu; uz aukstajiem burtiem kondensāts kā sīkas lēcas; apakšā peļķe ar atspulgu.\nuniform float uRnd[32];\nuniform sampler2D uTex0;   // vārda maska (izplūdusi, augstuma karte)\nuniform sampler2D uTex1;   // sarmas rīts, ass\nuniform sampler2D uTex2;   // sarmas rīts, izplūdis\nuniform float uBgAspect;\nuniform sampler2D uTex3;   // lāšu normāļu karte no fizikas (rg normāle, b pārklājums, a: 1 = krītoša lāse)\nuniform vec4 uRip[6];      // peļķes viļņi: x (0..1), vecums (s), stiprums\n\nvec3 bg(vec2 uv) {\n  vec3 c = photoCover(uTex2, clamp(uv, 0., 1.), uBgAspect, vec2(.55, .62), false);\n  return c;\n}\nfloat dpos(vec2 uv) { return (uv.x + uv.y) * .5; }          // 0 = kreisā apakša (auksts), 1 = labā augša (silts)\n\nvoid main() {\n  vec2 fc = gl_FragCoord.xy;\n  float asp = uRes.x / uRes.y;\n  vec2 uv = fc / uRes;\n  vec2 p = (fc - .5 * uRes) / uRes.y;\n\n  vec3 col = bg(uv);\n  float d = dpos(uv);\n  float DEW = .555;\n  // siltā puse: saules dūmaka un putekļi; vēsā: zilgana migla\n  col = mix(col, col * vec3(.78, .9, 1.08) + vec3(.02, .04, .07), smoothstep(DEW, .1, d) * .55);\n  float warmK = smoothstep(.55, 1., d);\n  vec2 sunP = (uv - vec2(1.02, 1.04)) * vec2(asp, 1.);\n  float sunGlow = exp(-dot(sunP, sunP) * 2.2);\n  col = mix(col, col * vec3(1.25, .98, .70) + vec3(.07, .025, 0.), warmK * .85);   // silts krāsu tonis\n  col += vec3(1., .62, .28) * (.26 * warmK + .75 * sunGlow);                       // saules siltums stūrī\n  col += vec3(1., .80, .55) * .18 * sunGlow * (.6 + .4 * fbm(sunP * 3. + uTime * .05, 3)); // virmojošs gaiss\n  for (int i = 0; i < 26; i++) {\n    float fi = float(i);\n    vec2 dp = vec2(.5 + .5 * hash12(vec2(fi, 31.)), .45 + .55 * hash12(vec2(fi, 37.)));\n    float rad = .0012 + .005 * pow(hash12(vec2(fi, 41.)), 4.);\n    vec2 dd = (uv - dp) * vec2(asp, 1.);\n    col += vec3(1., .85, .6) * exp(-dot(dd, dd) / (rad * rad)) * .45;\n  }\n\n  // ---------- burti ----------\n  float m = texture(uTex0, uv).r;\n  float e = 1.5 / uRes.y;\n  float mx = texture(uTex0, uv + vec2(e, 0)).r - texture(uTex0, uv - vec2(e, 0)).r;\n  float my = texture(uTex0, uv + vec2(0, e)).r - texture(uTex0, uv - vec2(0, e)).r;\n  // ēna aiz burtiem (gaisma no labās augšas)\n  float shadow = texture(uTex0, uv + vec2(.004, .006)).r;\n  col *= 1. - .22 * shadow * (1. - m);\n  if (m > .02) {\n    vec3 n = normalize(vec3(-mx * 6., -my * 6., 1.));\n    // šīfera reljefs: slāņaini, smalki graudi\n    vec2 sp = p * vec2(1., 1.);\n    float layers = fbm(vec2(sp.x * 9., sp.y * 22.) + 1.5 * fbm(sp * 5., 3), 4);\n    float grain = fbm(sp * 260., 3);\n    n = normalize(n + vec3(.10 * grain, .08 * layers + .06 * grain, 0.));\n    vec3 slate = mix(vec3(.050, .070, .080), vec3(.10, .13, .14), .5 + .5 * layers) * (.85 + .2 * grain);\n    float cold = smoothstep(DEW, .2, d);\n    slate *= 1. - .25 * cold;                                          // mitrs = tumšāks\n    vec3 L = normalize(vec3(.6, .7, .45));\n    float dif = max(dot(n, L), 0.);\n    vec3 lit = slate * (vec3(1., .82, .62) * 1.4 * dif + vec3(.35, .42, .50) * .7);\n    float spec = pow(max(dot(reflect(-L, n), vec3(0, 0, 1)), 0.), mix(20., 70., cold));\n    lit += vec3(1., .85, .65) * spec * mix(.15, .6, cold);              // slapjais šīferis spīd\n    col = mix(col, lit, smoothstep(.35, .55, m));\n  }\n\n  // ūdens lāses no fizikas: caurspīdīgas lēcas. Zem lāses redzams tas pats šīferis (vai fons),\n  // nedaudz palielināts; tumšāka mala (pilnā iekšējā atstarošana), ass spīduma punkts pret sauli,\n  // kaustika pretējā pusē un maza, mīksta ēna prom no gaismas.\n  vec4 dm = texture(uTex3, uv);\n  float shA = texture(uTex3, uv + vec2(.0022, .0034)).b;\n  col *= 1. - .22 * smoothstep(.1, .8, shA) * (1. - smoothstep(.02, .3, dm.b));\n  if (dm.b > .02) {\n    vec2 n = (dm.rg - .5) * 2.;\n    float r = min(1., length(n));\n    float hh = sqrt(max(0., 1. - r * r));\n    float onLetter = smoothstep(.3, .6, m);\n    // kas redzams caur lāsi: uz burta tas pats šīferis (lāse to tikai palielina un mazliet izgaismo),\n    // ārpus burta apgriezts un saspiests fons\n    vec3 behind = mix(bg(uv - n * vec2(.010 / asp, .010)) , col, onLetter);\n    vec3 c = behind * (.88 + .18 * hh);                          // lēca savāc gaismu vidū\n    c *= 1. - .72 * smoothstep(.5, 1., r);                      // tumšā mala\n    vec2 L = vec2(.45, .55);                                     // gaisma no labās augšas\n    c += vec3(1., .86, .64) * .28 * exp(-dot(n + L * .78, n + L * .78) * 22.);   // kaustika pretējā pusē\n    float spec = exp(-dot(n - L * .6, n - L * .6) * 55.);\n    c += vec3(1., .97, .92) * spec * 1.9;                        // ass atspīdums\n    c += vec3(1., .9, .75) * exp(-dot(n - L * .45, n - L * .45) * 18.) * .10;\n    c += bg(vec2(1.) - uv * .5) * pow(r, 5.) * .08;              // Freneļa atspulgs malā\n    col = mix(col, c, smoothstep(.02, .25, dm.b));\n  }\n\n  // rasas punkta līnija: vienīgā apzināti taisnā līnija\n  float lineD = ((uv.x + uv.y) - 2. * DEW) / 1.4142;            // ar zīmi: + siltāk, - vēsāk\n  float wob = .012 * fbm(vec2((uv.x - uv.y) * 4., uTime * .06), 3);\n  float band = exp(-pow((lineD + wob) / .045, 2.));                // plata, mīksta josla, bez malām\n  float wisps = smoothstep(.15, .7, fbm(vec2((uv.x - uv.y) * 9., lineD * 30.) + vec2(uTime * .04, 0.), 4));\n  float outside = 1. - smoothstep(.3, .6, m);\n  col = mix(col, vec3(.86, .90, .92), band * (.10 + .14 * wisps) * outside);  // migla, kur tvaiks kondensējas\n\n  // peļķe apakšā: neregulāra mala, sūna un oļi, vārda atspulgs\n  float py = -.34 + .06 * fbm(vec2(p.x * 2.2, 1.), 4) + .015 * gnoise(vec2(p.x * 14., 2.));\n  if (p.y < py) {\n    float sy = py + .5;\n    float rw = 0.;\n    for (int k = 0; k < 6; k++) {\n      if (uRip[k].z <= 0.) continue;\n      vec2 rd = vec2((uv.x - uRip[k].x) * asp, (p.y - py) * 4.);\n      float rr = length(rd), fr = uRip[k].y * .22;\n      rw += sin((rr - fr) * 120.) * exp(-pow((rr - fr) * 18., 2.)) * exp(-uRip[k].y * 1.4) * uRip[k].z;\n    }\n    vec2 ruv = vec2(uv.x + .004 * sin(p.x * 50. + p.y * 260.) + rw * .004, sy + (sy - uv.y) * 3.2 + .006 * gnoise(p * 60.) + rw * .012);\n    vec3 refl = bg(ruv);\n    float rm = texture(uTex0, ruv).r;\n    refl = mix(refl, vec3(.04, .06, .07), smoothstep(.35, .55, rm) * .85);\n    vec3 water = mix(vec3(.03, .04, .035), refl * .9, .45 + .35 * smoothstep(py - .16, py, p.y));\n    float edge = smoothstep(.0, .012, py - p.y);\n    vec3 shore = mix(vec3(.10, .14, .05), vec3(.26, .30, .14), .5 + .5 * fbm(p * 120., 3));\n    col = mix(shore, water, edge);\n    vec4 pv = voronoi(p * 34., .9);\n    if (hash12(pv.zw) > .8 && length(p - pv.zw / 34.) < .012 && py - p.y < .05) col = mix(vec3(.13, .12, .11), vec3(.24, .21, .18), .5 + .5 * fbm(p * 200., 2));\n    col += vec3(.9, .8, .6) * smoothstep(.003, .0, abs(py - p.y - .012)) * .15;\n  }\n  // izplūdis priekšplāns: sarmota zāle kreisajā apakšā\n  float blades = 0.;\n  for (int i = 0; i < 8; i++) {\n    float fi = float(i);\n    float x0 = -.5 * asp + .02 + .2 * hash12(vec2(fi, 61.));\n    float y = p.y + .5;\n    float x = x0 + (.25 + .4 * hash12(vec2(fi, 62.))) * y * y;\n    float w = .012 * (1. - y * 1.4);\n    blades = max(blades, smoothstep(w + .025, w * .1, abs(p.x - x)) * smoothstep(.55, .3, y) * step(0., w));\n  }\n  col = mix(col, vec3(.10, .13, .14), blades * .5);\n  col *= .85 + .15 * smoothstep(1.2, .3, length((uv - .5) * vec2(asp * .7, 1.)));\n  outColor = vec4(finish(col * 1.05, fc), 1.);\n}\n",
"rasa": "// rasa: Daiņa fotogrāfija; lāse-lēca ar laušanu, sīktēli kā īstas ūdens lāses, maiga migla aiz navigācijas un paraksta\nuniform float uRnd[32];\nuniform sampler2D uTex0;   // galvenā bilde\nuniform sampler2D uTex1;   // 8 sīktēlu atlass\nuniform float uImgAspect;\nuniform vec2 uFocus;\nuniform sampler2D uTex2;   // iepriekšējā bilde (pārejai)\nuniform float uPrevAspect;\nuniform vec2 uPrevFocus;\nuniform float uTrans;      // 0..1 kopš pārslēgšanas; >=1 pāreja beigusies\nuniform vec2 uImpact;      // lāses trieciena vieta (ekrāna 0..1)\nuniform int uSel;\nuniform float uLensR;\nuniform int uMouseThumb;\n\nvec3 photoRaw(vec2 uv) { return photoCover(uTex0, clamp(uv, 0., 1.), uImgAspect, uFocus, false); }\nvec3 photoPrev(vec2 uv) { return photoCover(uTex2, clamp(uv, 0., 1.), uPrevAspect, uPrevFocus, false); }\n// pāreja: uz bildes uzkrīt lāse, un jaunā bilde izplešas no trieciena vietas kā vilnis ar laušanu malā\nvec3 photo(vec2 uv) {\n  if (uTrans >= 1.) return photoRaw(uv);\n  float asp = uRes.x / uRes.y;\n  vec2 d = (uv - uImpact) * vec2(asp, 1.);\n  float r = length(d);\n  float front = uTrans * uTrans * 1.6 + .02;\n  float edge = r - front - .025 * fbm(d * 6. + uTrans, 3);\n  float wave = exp(-edge * edge * 900.) ;\n  vec2 off = (r > 1e-4 ? d / r : vec2(0)) * wave * .025 * vec2(1. / asp, 1.);\n  vec3 a = photoPrev(uv - off), b = photoRaw(uv - off);\n  vec3 c = mix(b, a, smoothstep(-.01, .01, edge));\n  return c + vec3(1.) * wave * .12;\n}\n\n// ūdens lāse uz virsmas: lauž to, kas zem tās (apgriež un saspiež), ar Freneļa malu, spīdumu un ēnu\nvec3 dropLens(vec2 p, vec2 c, float R, vec3 base, vec2 uv, int thumb) {\n  vec2 q = (p - c) / R;\n  float r2 = dot(q, q);\n  if (r2 > 1.) return base;\n  float h = sqrt(1. - r2);\n  vec3 n = normalize(vec3(q, h * 1.25));\n  // laušana ar n=1.33: redzamais punkts nobīdās pretēji normālei; lielākā lāsē attēls apgriežas\n  vec3 col;\n  if (thumb < 0) {\n    // 1,9× palielinājums ap lāses centru + laušana malās\n    vec2 cuv = (c * uRes.y + .5 * uRes) / uRes;\n    vec2 d = q * R / 1.9 * (1. + .35 * (1. - h)) * vec2(uRes.y / uRes.x, 1.);\n    col = photo(cuv + d) * 1.04;\n  } else {\n    vec2 tq = -q * (.85 + .15 * h);                       // apgriezts attēls lāsē\n    vec2 tuv = vec2((float(thumb) + .5 + tq.x * .5) / 8., .5 + tq.y * .5);\n    col = pow(texture(uTex1, tuv).rgb, vec3(2.2)) * 1.05;\n  }\n  float fres = pow(1. - h, 3.);\n  col = mix(col, col * .45, smoothstep(.6, 1., sqrt(r2)) * .6);       // tumšāka mala (pilnā iekšējā atstarošanās)\n  col += vec3(1.) * fres * .18;\n  vec3 L = normalize(vec3(-.45, .55, .7));\n  float spec = pow(max(dot(reflect(-L, n), vec3(0, 0, 1)), 0.), 120.);\n  col += vec3(1.) * spec * 1.6;\n  col += vec3(1.) * exp(-dot(q - vec2(.38, -.45), q - vec2(.38, -.45)) * 30.) * .25;  // kaustikas atspīdums lāses lejasdaļā\n  float aa = 1. - smoothstep(.96, 1., sqrt(r2));\n  return mix(base, col, aa);\n}\n\nvoid main() {\n  vec2 fc = gl_FragCoord.xy;\n  float asp = uRes.x / uRes.y;\n  vec2 uv = fc / uRes;\n  vec2 p = (fc - .5 * uRes) / uRes.y;\n  bool mobile = asp < .9;\n\n  // 2,5D: viegla parallakse ar dziļumu (bez dziļuma kartes koncepcijā: centrs tuvāk)\n  vec3 col = photo(uv);\n\n  // migla aiz navigācijas labajā malā un aiz paraksta (nevis kaste)\n  float navFog = smoothstep(.34, .0, length((uv - vec2(1.0, .5)) * vec2(asp * 1.4, .75)));\n  float capFog = smoothstep(.55, .0, length((uv - vec2(.0, .0)) * vec2(asp * .9, 1.6)));\n  vec3 fogC = vec3(.04, .08, .03);\n  col = mix(col, fogC, SAT(navFog * .7 + capFog * .6));\n\n  // lēca, kas seko kursoram\n  vec2 m = (uMouse - .5 * uRes) / uRes.y;\n  float R = uLensR;\n  // ēna zem lēcas\n  float sd = length((p - m - vec2(.02, -.03)) / vec2(1., .9)) / R;\n  col *= 1. - .25 * smoothstep(1.2, .6, sd) * step(1., length((p - m) / R));\n  col = dropLens(p, m, R, col, uv, -1);\n\n  // sīktēli kā ūdens lāses\n  float tr = mobile ? .022 : .028;\n  for (int i = 0; i < 8; i++) {\n    float fi = float(i);\n    vec2 c = mobile ? vec2(-.5 * asp + .05 + fi * (tr * 2.3), .5 - .09)\n                    : vec2(.5 * asp - .06 - (7. - fi) * tr * 2.35, -.5 + .12);\n    float wob = uMouseThumb == i ? .06 * sin(uTime * 9.) : 0.;\n    float rr = tr * (i == uSel ? 1.12 : 1.) * (1. + .05 * (hash12(vec2(fi, 3.)) - .5) + wob);\n    // mīksta kontakta ēna\n    float sdd = length((p - c - vec2(.003, -.006)) / rr);\n    col *= 1. - .35 * smoothstep(1.25, .8, sdd) * step(1., length((p - c) / rr));\n    col = dropLens(p, c, rr, col, uv, i);\n    if (i == uSel) col += vec3(.95, 1., .9) * smoothstep(.04, .0, abs(length((p - c) / rr) - 1.12)) * .5;\n  }\n  // fotogrāfijai bez ACES: īstās krāsas paliek kā kamerā\n  col = pow(max(col, 0.), vec3(1. / 2.2));\n  col += (hash12(fc) - .5) * (1.5 / 255.);\n  outColor = vec4(col, 1.);\n}\n",
"tinte": "// tinte: glāze no sāniem pret logu; tinte krīt, veido virpuļgredzenu, kas sadalās mazākos; uz galda krāsaina ēna\nuniform float uRnd[32];\nuniform sampler2D uTex0;\nuniform sampler2D uTex1;    // tintes blīvums no simulācijas\nuniform float uInkAmount;    // cik tintes kopā (ēnas krāsai uz galda)\nuniform float uRefr;\nuniform float uBgAspect;\n\nvec3 inkAbs;       // cik stipri tinte absorbē katru krāsu (indigo laiž cauri zilo)\n\nvec3 windowLight(vec2 uv) {\n  // aiz loga: Daiņa mežs, ļoti izplūdis un pārgaismots\n  vec3 c = photoCover(uTex0, clamp(uv, 0., 1.), uBgAspect, vec2(.5, .6), false);\n  c = mix(vec3(luma(c)), c, .8) * 1.9 + vec3(.10, .11, .10);\n  return c;\n}\n\n// tintes blīvums: virpuļgredzens ar kāju un sīkākiem gredzeniem zem tā\nfloat ringBlob(vec2 q, vec2 c, float R, float r) {\n  // gredzens no sāniem izskatās kā divi blīvi kodoli ar plānu \"cepuri\" virs tiem\n  vec2 d1 = q - (c + vec2(-R, 0)), d2 = q - (c + vec2(R, 0));\n  float cores = exp(-dot(d1, d1) / (r * r)) + exp(-dot(d2, d2) / (r * r));\n  vec2 dc = (q - c - vec2(0, r * .6)) / vec2(R * 1.25, r * 1.1);\n  float cap = exp(-dot(dc, dc)) * .55;\n  return cores + cap;\n}\n\nfloat inkDensity(vec2 q, float W) {\n  // q: glāzes koordinātās (x: -1..1 platumā, y: 0 dibens .. 1 ūdens virsma)\n  vec2 w = q + .045 * vec2(fbm(q * 7. + 3., 4), fbm(q * 7. + 11., 4));\n  w += .015 * vec2(fbm(q * 26., 3), fbm(q * 26. + 4., 3));\n  float d = 0.;\n  float cx = -.08 + .16 * uRnd[0];\n  float ry = .48 + .12 * uRnd[1];\n  // kāja: plāns pavediens no virsmas līdz gredzenam\n  float stemX = cx + .03 * gnoise(vec2(w.y * 5., 1.));\n  d += .55 * exp(-pow((w.x - stemX) / (.018 + .02 * (1. - w.y)), 2.)) * smoothstep(ry, ry + .06, w.y) * smoothstep(1.0, .9, w.y);\n  // galvenais gredzens\n  d += 1.6 * ringBlob(w, vec2(cx, ry), .16, .055);\n  // gredzens sadalās mazākos, kas krīt zemāk\n  for (int i = 0; i < 4; i++) {\n    float fi = float(i);\n    float a = (fi - 1.5) / 1.5;\n    vec2 c = vec2(cx + a * (.20 + .05 * hash12(vec2(fi, 3.))), ry - .14 - .08 * hash12(vec2(fi, 5.)) - .05 * abs(a));\n    d += 1.1 * ringBlob(w, c, .055, .025);\n    // vēl mazāki zem tiem\n    for (int j = 0; j < 2; j++) {\n      float fj = float(j);\n      vec2 c2 = c + vec2((fj - .5) * .07, -.09 - .04 * hash12(vec2(fi, fj + 7.)));\n      d += .7 * ringBlob(w, c2, .022, .012);\n      // tievi pavedieni, kas savieno\n      float tx = mix(c.x, c2.x, SAT((c.y - w.y) / max(c.y - c2.y, .01)));\n      d += .35 * exp(-pow((w.x - tx) / .006, 2.)) * step(c2.y, w.y) * step(w.y, c.y);\n    }\n  }\n  // izkliedēts plīvurs ap visu\n  d += .25 * smoothstep(.3, .8, fbm(w * 4. + 2., 4)) * exp(-pow((w.x - cx) / .35, 2.)) * smoothstep(.15, .5, w.y) * smoothstep(1.0, .7, w.y);\n  return d;\n}\n\nvoid main() {\n  vec2 fc = gl_FragCoord.xy;\n  float asp = uRes.x / uRes.y;\n  vec2 uv = fc / uRes;\n  vec2 p = (fc - .5 * uRes) / uRes.y;\n  bool mobile = asp < .9;\n\n  // tintes krāsa pēc sēklas: indigo, mellenes vai ozolu riekstu tinte\n  float pick = uRnd[9];\n  inkAbs = pick < .6 ? vec3(2.6, 2.2, .55) : (pick < .85 ? vec3(1.6, 2.6, 1.0) : vec3(1.4, 1.7, 2.3));\n\n  // telpa: logs aiz glāzes, galds apakšā\n  float tableY = mobile ? -.22 : -.20;\n  vec3 col = windowLight(uv);\n  // loga rāmja ēna kreisajā pusē un iekštelpas krēsla\n  col *= mix(.25, 1., smoothstep(-.6 * asp, -.2 * asp, p.x + .03 * gnoise(vec2(p.y * 3., 2.))));\n\n  // galds: mitra, gaiša koka virsma perspektīvā\n  if (p.y < tableY) {\n    float z = 1. / max(.02, tableY - p.y + .08);\n    vec2 tq = vec2(p.x * z * .2, z * .5);\n    float grain = fbm(vec2(tq.x * 2., tq.y * 18.), 4);\n    vec3 wood = mix(vec3(.38, .28, .19), vec3(.56, .44, .32), .5 + .5 * grain);\n    col = wood * (.7 + .3 * smoothstep(-.5, tableY, p.y));\n    col += windowLight(vec2(uv.x, 1. - uv.y)) * .10 * smoothstep(tableY - .12, tableY, p.y);\n  }\n\n  // glāze\n  float gx = mobile ? .04 * asp : .10 * asp;\n  float gw = mobile ? .36 * asp : .23;\n  float gBot = tableY - .11, gTop = mobile ? .36 : .40, waterY = mobile ? .26 : .29;\n  float xn = (p.x - gx) / gw;\n  float yn = (p.y - gBot) / (waterY - gBot);\n\n  // ēna un kaustika uz galda: gaisma nāk no loga aizmugurē, tāpēc ēna krīt uz priekšu (lejup ekrānā)\n  if (p.y < tableY) {\n    float fwd = SAT((gBot - p.y) / .30);\n    float hw2 = gw * (1. + .35 * fwd);\n    float shx = (p.x - gx - .04 * fwd) / hw2;\n    float sh = smoothstep(1.05, .55, abs(shx)) * smoothstep(-.02, .02, gBot + .005 - p.y) * (1. - fwd * .65);\n    vec3 tint = exp(-inkAbs * .7 * uInkAmount);\n    col *= mix(vec3(1.), mix(vec3(.35), tint * .8 + .1, .8), sh * .75);\n    // cilindriskās lēcas fokuss: spoža josla ēnas vidū\n    float caustic = exp(-pow(shx / (.18 + .2 * fwd), 2.)) * sh * (1. - .4 * fwd);\n    col += vec3(1., .96, .88) * caustic * .55 * (.6 + .4 * fbm(vec2(shx * 4., p.y * 30.), 3));\n    col += tint * caustic * .35 * uInkAmount;\n  }\n\n  if (abs(xn) < 1. && p.y > gBot && p.y < gTop) {\n    // cilindriska lēca: fons glāzē palielināts un apgriezts\n    float lens = xn * (1. - .55 * (1. - xn * xn));\n    vec2 buv = vec2((gx + lens * gw * -.85) / asp + .5, uv.y);\n    bool inWater = p.y < waterY + .012 * (pow(abs(xn), 8.));   // menisks pie sienām\n    vec3 inside;\n    if (inWater) {\n      inside = windowLight(buv) * vec3(.93, .97, .98);\n      vec2 q = vec2(xn, yn);\n      vec2 sq = vec2(lens * .5 + .5, yn);   // laušana: tinte redzama caur cilindrisko lēcu\n      float dens = texture(uTex1, clamp(sq, 0., 1.)).r;\n      dens += .25 * (texture(uTex1, sq + vec2(.006, 0)).r - texture(uTex1, sq - vec2(.006, 0)).r) * 0.;\n      inside *= exp(-inkAbs * dens * .9);\n      // gaisma, kas izkliedējas tintes malās\n      inside += exp(-inkAbs * .4) * .06 * smoothstep(.1, .6, dens) * (1. - smoothstep(.6, 2.2, dens));\n    } else {\n      inside = windowLight(vec2((gx + xn * gw * 1.02) / asp + .5, uv.y)) * .97;\n    }\n    // ūdens virsma no sāniem: plāna gaiša līnija ar meniska izliekumu\n    float surf = smoothstep(.006, .0, abs(p.y - waterY - .012 * pow(abs(xn), 8.)));\n    inside = mix(inside, vec3(1.15), surf * .5);\n    inside *= .95 - .2 * smoothstep(.0, -.05, p.y - waterY) * (1. - step(p.y, waterY));\n    // sienas: tumšāka mala ar atspīdumiem\n    float wall = smoothstep(.86, 1., abs(xn));\n    inside = mix(inside, inside * .55 + vec3(.05), wall);\n    inside += vec3(1.) * smoothstep(.035, .0, abs(xn + .80)) * .45;\n    inside += vec3(1.) * smoothstep(.02, .0, abs(xn - .9)) * .25;\n    // glāzes dibens: biezs stikls\n    float base = smoothstep(.03, .0, p.y - gBot - .025);\n    inside = mix(inside, inside * .7 + vec3(.12, .13, .13), base);\n    float aa = 1. - smoothstep(.985, 1., abs(xn));\n    col = mix(col, inside, aa);\n  }\n  // malas augšā: glāzes mala\n  float rimY = gTop;\n  col += vec3(.9) * smoothstep(.004, .0, abs(p.y - rimY)) * step(abs(xn), 1.) * .5;\n\n  col *= .82 + .18 * smoothstep(1.2, .3, length((uv - vec2(.55, .5)) * vec2(asp * .7, 1.)));\n  outColor = vec4(finish(col * .95, fc), 1.);\n}\n",
"tinte_sim": "// tintes simulācija: blīvuma lauks, ko nes virpuļgredzenu (punktvirpuļu pāru) ātrumu lauks + rotora troksnis.\n// Režģa koordinātas: x 0..1 glāzes platumā, y 0 (dibens) .. 1 (ūdens virsma). uAsp = platums/augstums.\nuniform sampler2D uTex0;      // iepriekšējais blīvums (r = tinte)\nuniform vec4 uVort[24];       // x, y, cirkulācija, kodola rādiuss\nuniform int uNV;\nuniform vec4 uInject;         // x, y, rādiuss, daudzums šajā kadrā\nuniform float uDt;\nuniform float uAsp;\nuniform float uDecay;\n\nvec2 velocity(vec2 q) {\n  vec2 v = vec2(0);\n  for (int i = 0; i < 24; i++) {\n    if (i >= uNV) break;\n    vec4 V = uVort[i];\n    vec2 r = (q - V.xy) * vec2(uAsp, 1.);\n    float r2 = dot(r, r) + V.w * V.w;\n    v += V.z * vec2(-r.y, r.x) / (6.2832 * r2) * vec2(1. / uAsp, 1.);\n  }\n  // lēna konvekcija un smalkas turbulences, kas aug, gredzeniem palēninoties\n  vec2 p = q * vec2(uAsp, 1.) * 5. + vec2(0., uTime * .05);\n  float e = .02;\n  float n0 = fbm(p, 3);\n  vec2 curl = vec2(fbm(p + vec2(0, e), 3) - n0, -(fbm(p + vec2(e, 0), 3) - n0)) / e;\n  v += curl * .010 * vec2(1. / uAsp, 1.);\n  v.y -= .004;                                  // tinte ir mazliet smagāka par ūdeni\n  return v;\n}\n\nvoid main() {\n  vec2 q = gl_FragCoord.xy / uRes;\n  // pusslāņa (MacCormack) vietā vienkāršs atpakaļizsekojums divos soļos\n  vec2 v1 = velocity(q);\n  vec2 mid = q - v1 * uDt * .5;\n  vec2 v2 = velocity(mid);\n  vec2 src = q - v2 * uDt;\n  float d = texture(uTex0, src).r;\n  // neliela difūzija\n  vec2 px = 1. / uRes;\n  float blur = (texture(uTex0, src + vec2(px.x, 0)).r + texture(uTex0, src - vec2(px.x, 0)).r +\n                texture(uTex0, src + vec2(0, px.y)).r + texture(uTex0, src - vec2(0, px.y)).r) * .25;\n  d = mix(d, blur, clamp(uDt * 1.2, 0., .2));\n  d *= uDecay;\n  // injekcija: krītošā lāse\n  vec2 ir = (q - uInject.xy) * vec2(uAsp, 1.);\n  d += uInject.w * exp(-dot(ir, ir) / (uInject.z * uInject.z));\n  // glāzes sienas un dibens: tinte nevar izkļūt\n  d *= smoothstep(0., .01, q.x) * smoothstep(1., .99, q.x) * smoothstep(0., .01, q.y);\n  outColor = vec4(min(d, 6.), 0, 0, 1);\n}\n"
};
